mapper.select:
select a.id, a.application_no as applicationNo, a.match_id as matchId, m.match_no as matchNo,
       a.exception_type as exceptionType, a.application_status as applicationStatus,
       a.decision_type as decisionType, a.applicant_team_id as applicantTeamId,
       a.exception_reason as exceptionReason, a.create_time as createTime,
       a.processed_time as processedTime
from basket_match_exception_application a
join basket_match m on m.id = a.match_id and m.is_delete = 0
where a.is_delete = 0
and a.season_id = #{seasonId}
and a.match_id = #{matchId}
and a.application_status = #{applicationStatus}
and a.exception_type = #{exceptionType}
order by a.create_time desc, a.id desc
